import { useEffect, useRef } from "react";
import { Link } from "wouter";
import { ArrowLeft } from "lucide-react";

/**
 * Customer PB, Indicator, Panel Wiring & Safety Logic Requirement Form.
 *
 * This form is plain HTML/CSS/JS (not React) so it is injected via a ref
 * rather than JSX. The HTML (including its own <style> block) is set via
 * innerHTML; the JS is injected as a real <script> element because
 * innerHTML does NOT execute embedded <script> tags in the browser.
 *
 * IMPORTANT: keep this as the only top-level component in this file
 * (Bug Pattern 02 - never define a component inside another component).
 */

const FORM_HTML = "<style>\n  body{font-family:Arial,Helvetica,sans-serif;color:#1f2937;background:#f1f5f9;margin:0;padding:0;}\n  #pbSafetyFormRoot{max-width:1150px;margin:0 auto;background:#fff;padding:24px;box-shadow:0 0 24px rgba(0,0,0,.06);}\n  #pbSafetyFormRoot h2.sec-title{background:#eaf1ff;border-left:5px solid #2563eb;color:#2563eb;padding:10px 14px;font-size:19px;margin:34px 0 14px;border-radius:4px;}\n  #pbSafetyFormRoot table.req-table{width:100%;border-collapse:collapse;margin-bottom:8px;font-size:13.5px;}\n  #pbSafetyFormRoot table.req-table th{background:#1d4ed8;color:#fff;padding:8px 10px;text-align:left;border:1px solid #1d4ed8;}\n  #pbSafetyFormRoot table.req-table td{border:1px solid #cbd5e1;padding:7px 9px;vertical-align:top;}\n  #pbSafetyFormRoot table.req-table tr:nth-child(even) td{background:#f8fafc;}\n  #pbSafetyFormRoot input[type=text], #pbSafetyFormRoot input[type=number], #pbSafetyFormRoot input[type=date], #pbSafetyFormRoot textarea, #pbSafetyFormRoot select{\n    width:100%;box-sizing:border-box;border:1px solid #cbd5e1;border-radius:4px;padding:5px 7px;font-size:13px;font-family:inherit;background:#fff;}\n  #pbSafetyFormRoot textarea{resize:vertical;min-height:34px;}\n  #pbSafetyFormRoot .compliance-radio label{display:inline-flex;align-items:center;gap:3px;margin-right:10px;font-size:12.5px;white-space:nowrap;}\n  #pbSafetyFormRoot .btn-row{display:flex;flex-wrap:wrap;gap:10px;margin:18px 0 10px;}\n  #pbSafetyFormRoot .btn{cursor:pointer;border:none;border-radius:6px;padding:10px 18px;font-size:14px;font-weight:600;color:#fff;}\n  #pbSafetyFormRoot .btn-save{background:#2563eb;} #pbSafetyFormRoot .btn-load{background:#0891b2;}\n  #pbSafetyFormRoot .btn-xlsx{background:#15803d;} #pbSafetyFormRoot .btn-pdf{background:#b91c1c;}\n  #pbSafetyFormRoot .btn-submit{background:#7c3aed;font-size:16px;padding:14px 26px;}\n  #pbSafetyFormRoot .note-box{background:#fff7ed;border:1px solid #fdba74;border-radius:6px;padding:10px 14px;font-size:13px;margin:10px 0;}\n  #pbSafetyFormRoot .ref-note{font-size:12.5px;color:#475569;margin:6px 0 10px;}\n  #pbSafetyFormRoot .tag-pill{display:inline-block;background:#eef2ff;color:#3730a3;font-size:11.5px;border-radius:999px;padding:3px 10px;margin:0 5px 5px 0;}\n  #pbSafetyFormRoot .col-narrow{width:38px;text-align:center;}\n  #pbSafetyFormRoot .col-mid{width:150px;}\n  #pbSafetyFormRoot .col-colour{width:130px;}\n  #pbSafetyFormRoot .signoff-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px;}\n  #pbSafetyFormRoot .customer-badge{display:inline-block;background:#fde68a;color:#92400e;font-weight:700;font-size:12px;border-radius:6px;padding:5px 12px;margin-bottom:10px;}\n  #pbSafetyFormRoot .summary-box{background:#f0fdf4;border:2px solid #22c55e;border-radius:8px;padding:16px 20px;margin:16px 0;}\n  #pbSafetyFormRoot .summary-box h3{color:#166534;margin-top:0;}\n  #pbSafetyFormRoot .summary-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:10px;margin-top:10px;}\n  #pbSafetyFormRoot .summary-card{background:#fff;border:1px solid #bbf7d0;border-radius:6px;padding:10px 12px;}\n  #pbSafetyFormRoot .summary-card .num{font-size:22px;font-weight:800;color:#166534;}\n  #pbSafetyFormRoot .summary-card .lbl{font-size:12px;color:#475569;}\n  @media (max-width:700px){ #pbSafetyFormRoot .signoff-grid{grid-template-columns:1fr;} }\n  #pdfPrintOverlay table{border-collapse:collapse;width:100%;} #pdfPrintOverlay td,#pdfPrintOverlay th{border:1px solid #94a3b8;padding:5px 7px;font-size:11px;}\n  #pbSafetyFormRoot .lock-options{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:16px;margin:14px 0 20px;}\n  #pbSafetyFormRoot .lock-option{border:1px solid #cbd5e1;border-radius:8px;padding:12px;text-align:center;background:#f8fafc;}\n  #pbSafetyFormRoot .lock-option img{width:100%;height:180px;object-fit:contain;border-radius:6px;background:#fff;display:block;margin-bottom:8px;border:1px solid #e2e8f0;}\n  #pbSafetyFormRoot .lock-option label{display:flex;align-items:center;justify-content:center;gap:6px;font-size:13px;font-weight:600;cursor:pointer;}\n  #pbSafetyFormRoot .tick-cross label{display:inline-flex;align-items:center;gap:4px;margin-right:14px;font-size:18px;cursor:pointer;}\n  #pbSafetyFormRoot .tick-cross .tick{color:#16a34a;font-weight:800;}\n  #pbSafetyFormRoot .tick-cross .cross{color:#dc2626;font-weight:800;}\n  #pbSafetyFormRoot table.req-table.wide-table{min-width:1360px;}\n  #pbSafetyFormRoot table.req-table.wide-table select{width:auto;min-width:112px;}\n</style>\n<div id=\"pbSafetyFormRoot\">\n\n<div>\n  <span class=\"customer-badge\">FOR CUSTOMER COMPLETION</span><br>\n  <span class=\"tag-pill\">##PB</span>\n  <span class=\"tag-pill\">##Indicators</span>\n  <span class=\"tag-pill\">##PanelDesign</span>\n  <span class=\"tag-pill\">##WireColorCode</span>\n  <span class=\"tag-pill\">##SafetyLogic</span>\n  <span class=\"tag-pill\">##TowerLamp</span>\n  <span class=\"tag-pill\">##DoorEmergency</span>\n</div>\n\n<h1 style=\"background:linear-gradient(90deg,#3b82f6,#6366f1);-webkit-background-clip:text;background-clip:text;color:transparent;font-size:28px;font-weight:800;margin:16px 0 4px;\">\n  Push Buttons, Indicators, Panel Wiring &amp; Safety Logic\n</h1>\n<p style=\"text-align:center;font-size:15px;color:#334155;margin:0 0 6px;\">Detailed Electrical Design Requirement &amp; Customer Sign-off Form \u2014 Special Purpose Machines (SPM)</p>\n<hr style=\"border:none;border-top:3px solid #2563eb;margin:16px 0 6px;\">\n<div class=\"note-box\">\n  <b>Instructions for the customer:</b> Please review every section with your electrical / automation team, select the correct colour from each dropdown, mark Compliance for every checklist point, and fill the Project Information and Sign-off sections. When finished, scroll to the bottom and click <b>\"Submit Completed Form\"</b> \u2014 this will (1) show a summary of counts, (2) download the completed Excel and PDF files, and (3) open a pre-filled email addressed back to DRB TechVerse. Please attach the two downloaded files to that email before sending.\n</div>\n\n<div class=\"btn-row\">\n  <button class=\"btn btn-save\" onclick=\"pbForm_saveDraft()\">\ud83d\udcbe Save Draft (this device)</button>\n  <button class=\"btn btn-load\" onclick=\"pbForm_loadDraftPrompt()\">\ud83d\udcc2 Load Draft</button>\n</div>\n<div id=\"pbFormStatusMsg\" style=\"font-size:12.5px;color:#16a34a;min-height:16px;\"></div>\n\n<!-- 1. PROJECT INFORMATION -->\n<h2 class=\"sec-title\">1. Project Information</h2>\n<table class=\"req-table\">\n  <tr><th style=\"width:220px;\">Field</th><th>Details</th></tr>\n  <tr><td>Project Name</td><td><input type=\"text\" id=\"f_proj_name\"></td></tr>\n  <tr><td>Project / Code Number</td><td><input type=\"text\" id=\"f_proj_code\"></td></tr>\n  <tr><td>Customer Name</td><td><input type=\"text\" id=\"f_proj_customer\"></td></tr>\n  <tr><td>Machine / Module Name</td><td><input type=\"text\" id=\"f_proj_machine\"></td></tr>\n  <tr><td>Site Location</td><td><input type=\"text\" id=\"f_proj_site\"></td></tr>\n  <tr><td>Form Prepared By (Engineer)</td><td><input type=\"text\" id=\"f_proj_preparedby\"></td></tr>\n  <tr><td>Date</td><td><input type=\"date\" id=\"f_proj_date\"></td></tr>\n</table>\n\n<!-- 2. PB / INDICATOR / TOWER LAMP DEVICE LIST -->\n<h2 class=\"sec-title\">2. Push Buttons, Indicators &amp; Tower Lamp \u2014 Device List</h2>\n<p class=\"ref-note\">List every hardwired device required on the panel/HMI door. Select the actual Colour (and Background Colour, where applicable \u2014 e.g. Emergency Stop) from the dropdown; enter quantity and any special note.</p>\n<div id=\"pbDeviceTableWrap\"></div>\n\n<!-- 3. PANEL REQUIREMENTS CHECKLIST -->\n<h2 class=\"sec-title\">3. Electrical Panel Requirements \u2014 Checklist</h2>\n<div id=\"panelReqTableWrap\"></div>\n\n<p class=\"ref-note\" style=\"margin-top:18px;\"><b>Door Lock / Handle Type</b> \u2014 select the lock type required for this panel's door(s).</p>\n<div id=\"doorLockOptionsWrap\"></div>\n\n<!-- 4. WIRE COLOUR CODING -->\n<h2 class=\"sec-title\">4. Standard Colour Coding for Electrical Wiring</h2>\n<p class=\"ref-note\">\"Standard Colour\" is the reference/recommended colour. Use the \"Selected Colour\" dropdown to confirm the colour actually being used for this project (defaults to the standard).</p>\n<div id=\"wireColorTableWrap\"></div>\n\n<!-- 5. SAFETY INDICATOR LIGHT LOGIC -->\n<h2 class=\"sec-title\">5. Safety Indicator Light Logic</h2>\n<div class=\"note-box\">Every module must have its own Safety Indicator, visible from every angle around the machine.</div>\n<div id=\"safetyLogicTableWrap\" style=\"overflow-x:auto;\"></div>\n\n<!-- 6. TOWER LAMP LOGIC -->\n<h2 class=\"sec-title\">6. Tower Lamp Status Logic</h2>\n<p class=\"ref-note\">Each module's tower lamp must follow this colour logic.</p>\n<div id=\"towerLampTableWrap\"></div>\n\n<!-- 7. DOOR SAFETY & RESET LOGIC -->\n<h2 class=\"sec-title\">7. Door Safety &amp; Reset Logic</h2>\n<div id=\"doorLogicTableWrap\"></div>\n<div class=\"note-box\"><b>Note \u2014 Restart condition (Ref. 7.4):</b> Automatic restarts are not allowed. A physical reset shall occur prior to a machine restart \u2014 e.g. an interlocked guard-door safety system shall be designed so that simply re-closing the door does not by itself cause any machine motion.</div>\n\n<!-- 8. EMERGENCY STOP & RESET LOGIC -->\n<h2 class=\"sec-title\">8. Emergency Stop &amp; Reset Logic</h2>\n<div id=\"emergencyLogicTableWrap\"></div>\n\n<!-- 9. LIGHT CURTAIN LOGIC -->\n<h2 class=\"sec-title\">9. Light Curtain Logic</h2>\n<div id=\"lightCurtainTableWrap\"></div>\n\n<!-- 10. SIGN-OFF -->\n<h2 class=\"sec-title\">10. Review &amp; Customer Sign-off</h2>\n<div class=\"signoff-grid\">\n  <table class=\"req-table\">\n    <tr><th colspan=\"2\">Prepared By (Controls Engineer)</th></tr>\n    <tr><td style=\"width:130px;\">Name</td><td><input type=\"text\" id=\"f_signoff_eng_name\"></td></tr>\n    <tr><td>Designation</td><td><input type=\"text\" id=\"f_signoff_eng_desg\"></td></tr>\n    <tr><td>Date</td><td><input type=\"date\" id=\"f_signoff_eng_date\"></td></tr>\n  </table>\n  <table class=\"req-table\">\n    <tr><th colspan=\"2\">Reviewed &amp; Approved By (Customer)</th></tr>\n    <tr><td style=\"width:130px;\">Name</td><td><input type=\"text\" id=\"f_signoff_cust_name\"></td></tr>\n    <tr><td>Designation</td><td><input type=\"text\" id=\"f_signoff_cust_desg\"></td></tr>\n    <tr><td>Date</td><td><input type=\"date\" id=\"f_signoff_cust_date\"></td></tr>\n  </table>\n</div>\n<table class=\"req-table\" style=\"margin-top:10px;\">\n  <tr><th style=\"width:220px;\">General Comments / Deviations</th><td><textarea id=\"f_signoff_comments\" rows=\"3\"></textarea></td></tr>\n</table>\n\n<!-- 11. SUBMIT -->\n<h2 class=\"sec-title\">11. Submit Completed Form</h2>\n<p class=\"ref-note\">Clicking Submit will generate a summary of quantities/colours below, download the completed Excel and PDF, and open a pre-filled email back to DRB TechVerse. Please attach the two downloaded files before sending the email.</p>\n<div class=\"btn-row\">\n  <button class=\"btn btn-xlsx\" onclick=\"pbForm_downloadExcel()\">\ud83d\udcca Download Excel</button>\n  <button class=\"btn btn-pdf\" onclick=\"pbForm_downloadPDF()\">\ud83d\udcc4 Download PDF</button>\n  <button class=\"btn btn-submit\" onclick=\"pbForm_submit()\">\u2705 Submit Completed Form</button>\n</div>\n\n<div id=\"summaryPanel\"></div>\n\n</div>";

const FORM_JS = "\n(function(){\n\n// ======= CONFIG =======\nvar ADMIN_EMAIL = \"admin@drbtechverse.in\"; // change to the recipient inbox that should receive submissions\n\n// ---------- COLOUR PALETTE (shared dropdown list) ----------\nvar COLOR_OPTIONS = [\"Red\",\"Yellow\",\"Green\",\"Blue\",\"Black\",\"White\",\"Gray\",\"Brown\",\"Orange\",\"Amber\",\"Yellow-Green\",\"Clear / Transparent\",\"N/A\"];\nvar MAIN_AIR_OPTIONS = [\"ON\",\"OFF\",\"\u2014\"];\nvar SAFETY_INDICATOR_OPTIONS = [\"OFF\",\"ON\",\"Green ON\",\"Green OFF\",\"Green Blinking\",\"Yellow ON\",\"Yellow Blinking\",\"Yellow OFF\",\"Red ON\",\"Red OFF\",\"Red Blinking\",\"Red with Alarm\"];\nvar TOWER_LAMP_OPTIONS = [\"Green Steady\",\"Green Blinking\",\"Orange Blinking\",\"Orange Steady\",\"Red Steady\",\"Red Blinking\"];\nvar DOOR_LOCK_OPTIONS = [\n  {id:\"cylinder\", label:\"Key Cylinder Lock\", img:\"data:image/jpeg;base64,\"},\n  {id:\"twinhandle\", label:\"Handle Lock (Key Operated)\", img:\"data:image/jpeg;base64,\"},\n  {id:\"rittalhandle\", label:\"Rittal-Style Handle Lock (Key Operated)\", img:\"data:image/jpeg;base64,\"}\n];\n\n// ---------- DATA ----------\nvar PB_DEVICES = [\n  {device:\"Start Push Button\", type:\"Momentary, illuminated\", colour:\"Green\", background:\"\"},\n  {device:\"Stop Push Button\", type:\"Momentary\", colour:\"Red\", background:\"\"},\n  {device:\"Emergency Stop\", type:\"Mushroom head, latching, mounted on every door\", colour:\"Red\", background:\"Yellow\"},\n  {device:\"Safety Reset Push Button\", type:\"Illuminated\", colour:\"Blue\", background:\"\"},\n  {device:\"Auto / Manual Selector Switch\", type:\"Key or knob type\", colour:\"Black\", background:\"\"},\n  {device:\"Two-Hand Push Button Set\", type:\"Anti-tie-down\", colour:\"Black\", background:\"\"},\n  {device:\"Green Indicator Lamp\", type:\"Running / Ready status\", colour:\"Green\", background:\"\"},\n  {device:\"Yellow / Amber Indicator Lamp\", type:\"Warning status\", colour:\"Yellow\", background:\"\"},\n  {device:\"Red Indicator Lamp\", type:\"Fault / Alarm status\", colour:\"Red\", background:\"\"},\n  {device:\"Buzzer / Audible Alarm\", type:\"Alarm condition\", colour:\"N/A\", background:\"\"},\n  {device:\"Tower Lamp (3-tier R/Y/G)\", type:\"Per Section 6 logic \u2014 multi-colour\", colour:\"N/A\", background:\"\"}\n];\nvar PUSH_BUTTON_DEVICE_NAMES = [\"Start Push Button\",\"Stop Push Button\",\"Safety Reset Push Button\",\"Two-Hand Push Button Set\"];\nvar INDICATOR_LAMP_DEVICE_NAMES = [\"Green Indicator Lamp\",\"Yellow / Amber Indicator Lamp\",\"Red Indicator Lamp\"];\n\nvar PANEL_ITEMS = [\n  \"Panel ventilation provided (fan / louvre as required for heat load).\",\n  \"Standard colour coding of wires followed throughout the panel.\",\n  \"AC and DC supply wiring kept physically separated inside the panel.\",\n  \"All electrical components mounted to be easily accessible.\",\n  \"SMPS rating calculation provided (load-based sizing sheet attached).\",\n  \"Accessibility for cleaning and 5S housekeeping maintained inside panel.\",\n  \"ELCB 30mA provided on incoming supply.\",\n  \"Separate circuit breaker (MCB) provided for every AC component.\",\n  \"Separate circuit breaker for PLC/HMI and fuse-protected distribution for 24VDC control voltage.\",\n  \"All electrical components mounted at accessible height for easy maintenance.\",\n  \"Components are easily and individually replaceable without disturbing others.\",\n  \"Calibration certificate provided for all measuring &amp; testing equipment.\",\n  \"BOM provided with part number, make, supplier, and local-supplier details.\",\n  \"All related software (monitoring / debugging / modification) supplied with valid license.\",\n  \"Machine provided with a dedicated programming station (preferably a laptop).\",\n  \"All required communication cables (PLC-HMI, network, etc.) provided.\"\n];\n// each wire row: [item, standardColour, category]  category: 'power' | 'signal'\nvar WIRE_GROUPS = [\n  {supply:\"3-Phase AC Supply\", rows:[[\"L1 Phase\",\"Red\",\"power\"],[\"L2 Phase\",\"Yellow\",\"power\"],[\"L3 Phase\",\"Blue\",\"power\"],[\"Neutral\",\"Black\",\"power\"],[\"Earthing\",\"Yellow-Green\",\"power\"]]},\n  {supply:\"1-Phase AC Supply\", rows:[[\"Phase\",\"Red\",\"power\"],[\"Neutral\",\"Black\",\"power\"],[\"Earthing\",\"Yellow-Green\",\"power\"]]},\n  {supply:\"24V DC Supply\", rows:[[\"24V (+)\",\"Brown\",\"power\"],[\"0V (-)\",\"Blue\",\"power\"],[\"PLC Input\",\"White\",\"signal\"],[\"PLC Output\",\"Gray\",\"signal\"]]}\n];\nvar SAFETY_LOGIC = [\n  {n:1, cond:\"All doors closed\", mode:\"Auto Mode\", mainAir:\"ON\", elec:\"ON\", ctrl:\"OK\", indicator:\"OFF\", desc:\"Machine is running normally with all doors closed.\"},\n  {n:2, cond:\"All doors closed, Emergency pressed\", mode:\"Auto Mode\", mainAir:\"OFF\", elec:\"OFF\", ctrl:\"OK\", indicator:\"Green ON\", desc:\"All moving equipment (electrical &amp; pneumatic) stops.\"},\n  {n:3, cond:\"Any door open\", mode:\"Auto Mode\", mainAir:\"OFF\", elec:\"OFF\", ctrl:\"OK\", indicator:\"Green ON\", desc:\"All moving equipment (electrical &amp; pneumatic) stops.\"},\n  {n:4, cond:\"One set of door open\", mode:\"Setup Mode (with key operation)\", mainAir:\"ON\", elec:\"ON\", ctrl:\"OK\", indicator:\"Yellow ON\", desc:\"All functions operational at slow / step-by-step speed. Servo runs at 10% of rated speed with two-hand PB. Pneumatic runs in step function with two-hand PB.\"},\n  {n:5, cond:\"More than one set of door open\", mode:\"Setup Mode (with key operation)\", mainAir:\"OFF\", elec:\"OFF\", ctrl:\"OK\", indicator:\"Yellow Blinking\", desc:\"No operation possible \u2014 two-hand PB becomes inactive.\"},\n  {n:6, cond:\"Door close/open with controller fault\", mode:\"Setup / Auto Mode\", mainAir:\"\u2014\", elec:\"\u2014\", ctrl:\"NOK\", indicator:\"Red with Alarm\", desc:\"Safety controller fault condition.\"}\n];\nvar TOWER_LAMP = [\n  {n:1, colour:\"Green Blinking\", meaning:\"Machine in Auto Mode \u2014 Auto condition OK (no alarm) but Start button not yet pressed.\"},\n  {n:2, colour:\"Green Steady\", meaning:\"Machine in Auto Mode and running without any alarm.\"},\n  {n:3, colour:\"Orange Blinking\", meaning:\"Machine warning present in Auto Mode (Green light also ON).\"},\n  {n:4, colour:\"Orange Steady\", meaning:\"Machine in Manual Mode.\"},\n  {n:5, colour:\"Red Steady\", meaning:\"Machine stopped due to alarm / error in Auto Mode.\"}\n];\nvar DOOR_LOGIC = [\n  \"Any door opened and closed \u2014 the machine must not restart until the Safety Reset push button (blue, illuminated) is pressed.\",\n  \"If two doors are open simultaneously, no movement is allowed and both two-hand PBs become inactive.\",\n  \"For a 6-sided guarded machine with the two-hand PB at the front: in Setup Mode the front two-hand PB works for the front door only; if any back door is open, no operation is possible in Manual Mode.\",\n  \"If operation or maintenance is required from a back door, a two-hand PB must be provided at every back door opening.\"\n];\nvar EMERGENCY_LOGIC = [\n  \"Emergency stop mounted at every door opening \u2014 red button on a yellow background.\",\n  \"In Auto mode, pressing then releasing Emergency must NOT self-reset \u2014 the Reset push button must be pressed to clear the fault.\",\n  \"In Auto mode, after Emergency + Reset the machine should re-initialize and all in-process parts should be scrapped automatically.\",\n  \"In Semi-Auto mode, after Emergency is pressed the machine should either scrap the parts automatically, or the operator manually removes the part to the rejection bin.\"\n];\nvar LIGHT_CURTAIN_LOGIC = [\n  \"Light curtain mounted per the calculated safe distance \u2014 provide the safe-distance calculation.\",\n  \"Auto-reset may be allowed only where the part is loaded manually \u2014 must ensure no hazardous movement occurs when the curtain is interrupted.\",\n  \"During Auto running, if the light curtain is interrupted the machine must stop immediately (same behaviour as Emergency pressed).\"\n];\n\n// ---------- HELPERS ----------\nfunction complianceRadio(prefix){\n  return '<div class=\"compliance-radio\">'+\n    '<label><input type=\"radio\" name=\"'+prefix+'_status\" value=\"Provided\"> Provided</label>'+\n    '<label><input type=\"radio\" name=\"'+prefix+'_status\" value=\"Not Provided\"> Not Provided</label>'+\n    '<label><input type=\"radio\" name=\"'+prefix+'_status\" value=\"NA\"> N/A</label>'+\n    '</div>';\n}\nfunction remarkInput(id){ return '<input type=\"text\" id=\"'+id+'\" placeholder=\"Remark\">'; }\nfunction checkedRadioVal(prefix){\n  var el = document.querySelector('input[name=\"'+prefix+'_status\"]:checked');\n  return el ? el.value : \"\";\n}\nfunction v(id){ var e=document.getElementById(id); return e ? (e.value||\"\").trim() : \"\"; }\nfunction selectVal(id){ var e=document.getElementById(id); return e ? e.value : \"\"; }\nfunction colourSelect(id, defaultVal){\n  var html = '<select id=\"'+id+'\">';\n  var found = false;\n  COLOR_OPTIONS.forEach(function(c){\n    var sel = (c === defaultVal);\n    if(sel) found = true;\n    html += '<option value=\"'+c+'\"'+(sel?' selected':'')+'>'+c+'</option>';\n  });\n  if(!found && defaultVal){ html += '<option value=\"'+defaultVal+'\" selected>'+defaultVal+'</option>'; }\n  html += '</select>';\n  return html;\n}\nfunction simpleSelect(id, options, defaultVal){\n  var html = '<select id=\"'+id+'\">';\n  var found = false;\n  options.forEach(function(o){\n    var sel = (o === defaultVal);\n    if(sel) found = true;\n    html += '<option value=\"'+o+'\"'+(sel?' selected':'')+'>'+o+'</option>';\n  });\n  if(!found && defaultVal){ html += '<option value=\"'+defaultVal+'\" selected>'+defaultVal+'</option>'; }\n  html += '</select>';\n  return html;\n}\nfunction tickCrossRadio(name){\n  return '<div class=\"tick-cross\">'+\n    '<label><input type=\"radio\" name=\"'+name+'\" value=\"OK\"> <span class=\"tick\">&#10003;</span></label>'+\n    '<label><input type=\"radio\" name=\"'+name+'\" value=\"NOK\"> <span class=\"cross\">&#10007;</span></label>'+\n    '</div>';\n}\nfunction tickCrossVal(name){\n  var el = document.querySelector('input[name=\"'+name+'\"]:checked');\n  return el ? el.value : \"\";\n}\nfunction doorLockLabel(id){\n  var opt = DOOR_LOCK_OPTIONS.find(function(o){ return o.id === id; });\n  return opt ? opt.label : \"Not selected\";\n}\n\n// ---------- RENDERERS ----------\nfunction renderDeviceTable(){\n  var html = '<table class=\"req-table\"><tr><th class=\"col-narrow\">#</th><th>Device</th><th>Type / Function</th>'+\n    '<th class=\"col-colour\">Colour</th><th class=\"col-colour\">Background Colour</th><th style=\"width:80px;\">Qty</th><th>Remark</th></tr>';\n  PB_DEVICES.forEach(function(d,i){\n    html += '<tr><td class=\"col-narrow\">'+(i+1)+'</td><td>'+d.device+'</td><td>'+d.type+'</td>'+\n      '<td>'+colourSelect('f_pbdev'+i+'_colour', d.colour)+'</td>'+\n      '<td>'+colourSelect('f_pbdev'+i+'_bg', d.background || 'N/A')+'</td>'+\n      '<td><input type=\"number\" min=\"0\" id=\"f_pbdev'+i+'_qty\"></td>'+\n      '<td>'+remarkInput('f_pbdev'+i+'_remark')+'</td></tr>';\n  });\n  html += '</table>';\n  document.getElementById('pbDeviceTableWrap').innerHTML = html;\n}\nfunction renderChecklist(containerId, idPrefix, items){\n  var html = '<table class=\"req-table\"><tr><th class=\"col-narrow\">Sr</th><th>Requirement Point</th><th class=\"col-mid\">Compliance</th><th class=\"col-mid\">Remark</th></tr>';\n  items.forEach(function(text,i){\n    var p = idPrefix+i;\n    html += '<tr><td class=\"col-narrow\">'+(i+1)+'</td><td>'+text+'</td>'+\n      '<td>'+complianceRadio(p)+'</td><td>'+remarkInput(p+'_remark')+'</td></tr>';\n  });\n  html += '</table>';\n  document.getElementById(containerId).innerHTML = html;\n}\nfunction renderWireColor(){\n  var html = '<table class=\"req-table\"><tr><th>Supply</th><th>Wire / Point</th><th>Category</th><th>Standard Colour</th><th class=\"col-colour\">Selected Colour</th><th>Remark</th></tr>';\n  var globalIdx = 0;\n  WIRE_GROUPS.forEach(function(g,gi){\n    g.rows.forEach(function(row,ri){\n      html += '<tr>'+(ri===0 ? '<td rowspan=\"'+g.rows.length+'\"><b>'+g.supply+'</b></td>' : '')+\n        '<td>'+row[0]+'</td><td>'+(row[2]==='signal'?'Signal Cable':'Power Cable')+'</td><td>'+row[1]+'</td>'+\n        '<td>'+colourSelect('f_wirerow'+globalIdx+'_colour', row[1])+'</td>'+\n        (ri===0 ? '<td rowspan=\"'+g.rows.length+'\">'+remarkInput('f_wire'+gi+'_remark')+'</td>' : '')+\n        '</tr>';\n      globalIdx++;\n    });\n  });\n  html += '</table>';\n  document.getElementById('wireColorTableWrap').innerHTML = html;\n}\nfunction renderSafetyLogic(){\n  var html = '<table class=\"req-table wide-table\"><tr><th class=\"col-narrow\">#</th><th>Condition</th><th>Machine Mode</th><th>Main Air</th><th>Electrical Movement</th><th>Safety Controller</th><th>Safety Indicator</th><th>Description</th><th class=\"col-mid\">Compliance</th><th class=\"col-mid\">Remark</th></tr>';\n  SAFETY_LOGIC.forEach(function(r){\n    var p = 'f_saf'+r.n;\n    html += '<tr><td class=\"col-narrow\">'+r.n+'</td><td>'+r.cond+'</td><td>'+r.mode+'</td>'+\n      '<td>'+simpleSelect(p+'_mainair', MAIN_AIR_OPTIONS, r.mainAir)+'</td>'+\n      '<td>'+simpleSelect(p+'_elec', MAIN_AIR_OPTIONS, r.elec)+'</td>'+\n      '<td>'+tickCrossRadio(p+'_ctrl')+'</td>'+\n      '<td>'+simpleSelect(p+'_indicator', SAFETY_INDICATOR_OPTIONS, r.indicator)+'</td>'+\n      '<td>'+r.desc+'</td>'+\n      '<td>'+complianceRadio(p)+'</td><td>'+remarkInput(p+'_remark')+'</td></tr>';\n  });\n  html += '</table>';\n  document.getElementById('safetyLogicTableWrap').innerHTML = html;\n}\nfunction renderTowerLamp(){\n  var html = '<table class=\"req-table\"><tr><th class=\"col-narrow\">#</th><th>Tower Lamp State</th><th>Meaning</th><th class=\"col-mid\">Compliance</th><th class=\"col-mid\">Remark</th></tr>';\n  TOWER_LAMP.forEach(function(r){\n    var p = 'f_twr'+r.n;\n    html += '<tr><td class=\"col-narrow\">'+r.n+'</td><td>'+simpleSelect(p+'_state', TOWER_LAMP_OPTIONS, r.colour)+'</td><td>'+r.meaning+'</td>'+\n      '<td>'+complianceRadio(p)+'</td><td>'+remarkInput(p+'_remark')+'</td></tr>';\n  });\n  html += '</table>';\n  document.getElementById('towerLampTableWrap').innerHTML = html;\n}\n\nfunction renderDoorLockOptions(){\n  var html = '<div class=\"lock-options\">';\n  DOOR_LOCK_OPTIONS.forEach(function(opt){\n    html += '<div class=\"lock-option\">'+\n      '<img src=\"'+opt.img+'\" alt=\"'+opt.label+'\">'+\n      '<label><input type=\"radio\" name=\"f_doorlock_type\" value=\"'+opt.id+'\"> '+opt.label+'</label>'+\n      '</div>';\n  });\n  html += '</div>';\n  html += '<table class=\"req-table\" style=\"margin-top:6px;\"><tr><th style=\"width:220px;\">Additional Note on Lock Type</th><td>'+remarkInput('f_doorlock_remark')+'</td></tr></table>';\n  document.getElementById('doorLockOptionsWrap').innerHTML = html;\n}\n\nfunction renderAll(){\n  renderDeviceTable();\n  renderChecklist('panelReqTableWrap','f_pnl',PANEL_ITEMS);\n  renderDoorLockOptions();\n  renderWireColor();\n  renderSafetyLogic();\n  renderTowerLamp();\n  renderChecklist('doorLogicTableWrap','f_door',DOOR_LOGIC);\n  renderChecklist('emergencyLogicTableWrap','f_emg',EMERGENCY_LOGIC);\n  renderChecklist('lightCurtainTableWrap','f_lc',LIGHT_CURTAIN_LOGIC);\n}\nrenderAll();\n\n// ---------- DATA EXTRACTION ----------\nfunction collectFormData(){\n  var data = { project:{}, devices:[], panel:[], wire:[], wireRemarks:[], safety:[], tower:[], door:[], emergency:[], lightCurtain:[], doorLock:{}, signoff:{} };\n  [\"name\",\"code\",\"customer\",\"machine\",\"site\",\"preparedby\",\"date\"].forEach(function(k){\n    data.project[k] = v('f_proj_'+k);\n  });\n  PB_DEVICES.forEach(function(d,i){\n    data.devices.push({\n      device:d.device, type:d.type,\n      colour:selectVal('f_pbdev'+i+'_colour'),\n      background:selectVal('f_pbdev'+i+'_bg'),\n      qty:v('f_pbdev'+i+'_qty'), remark:v('f_pbdev'+i+'_remark')\n    });\n  });\n  PANEL_ITEMS.forEach(function(text,i){\n    data.panel.push({sr:i+1, point:text, status:checkedRadioVal('f_pnl'+i), remark:v('f_pnl'+i+'_remark')});\n  });\n  var globalIdx = 0;\n  WIRE_GROUPS.forEach(function(g,gi){\n    var groupRemark = v('f_wire'+gi+'_remark');\n    data.wireRemarks.push(groupRemark);\n    g.rows.forEach(function(row){\n      data.wire.push({supply:g.supply, item:row[0], standard:row[1], category:row[2], selected:selectVal('f_wirerow'+globalIdx+'_colour'), remark:groupRemark});\n      globalIdx++;\n    });\n  });\n  SAFETY_LOGIC.forEach(function(r){\n    var p = 'f_saf'+r.n;\n    data.safety.push({n:r.n, condition:r.cond, mode:r.mode,\n      mainAir:selectVal(p+'_mainair'), elec:selectVal(p+'_elec'), ctrl:tickCrossVal(p+'_ctrl'), indicator:selectVal(p+'_indicator'),\n      desc:r.desc, status:checkedRadioVal(p), remark:v(p+'_remark')});\n  });\n  TOWER_LAMP.forEach(function(r){\n    var p = 'f_twr'+r.n;\n    data.tower.push({n:r.n, colour:selectVal(p+'_state'), meaning:r.meaning, status:checkedRadioVal(p), remark:v(p+'_remark')});\n  });\n  DOOR_LOGIC.forEach(function(text,i){\n    data.door.push({sr:i+1, point:text, status:checkedRadioVal('f_door'+i), remark:v('f_door'+i+'_remark')});\n  });\n  EMERGENCY_LOGIC.forEach(function(text,i){\n    data.emergency.push({sr:i+1, point:text, status:checkedRadioVal('f_emg'+i), remark:v('f_emg'+i+'_remark')});\n  });\n  LIGHT_CURTAIN_LOGIC.forEach(function(text,i){\n    data.lightCurtain.push({sr:i+1, point:text, status:checkedRadioVal('f_lc'+i), remark:v('f_lc'+i+'_remark')});\n  });\n  var doorLockChecked = document.querySelector('input[name=\"f_doorlock_type\"]:checked');\n  data.doorLock = { type: doorLockChecked ? doorLockChecked.value : \"\", remark: v('f_doorlock_remark') };\n  [\"eng_name\",\"eng_desg\",\"eng_date\",\"cust_name\",\"cust_desg\",\"cust_date\",\"comments\"].forEach(function(k){\n    data.signoff[k] = v('f_signoff_'+k);\n  });\n  return data;\n}\nfunction applyFormData(data){\n  if(!data) return;\n  if(data.project) Object.keys(data.project).forEach(function(k){ var e=document.getElementById('f_proj_'+k); if(e) e.value=data.project[k]||''; });\n  (data.devices||[]).forEach(function(d,i){\n    var c=document.getElementById('f_pbdev'+i+'_colour'); if(c && d.colour) c.value=d.colour;\n    var b=document.getElementById('f_pbdev'+i+'_bg'); if(b && d.background) b.value=d.background;\n    var q=document.getElementById('f_pbdev'+i+'_qty'); if(q) q.value=d.qty||'';\n    var r=document.getElementById('f_pbdev'+i+'_remark'); if(r) r.value=d.remark||'';\n  });\n  function applyChecklist(arr,prefix){\n    (arr||[]).forEach(function(row,i){\n      var p=prefix+i;\n      if(row.status){ var radio=document.querySelector('input[name=\"'+p+'_status\"][value=\"'+row.status+'\"]'); if(radio) radio.checked=true; }\n      var r=document.getElementById(p+'_remark'); if(r) r.value=row.remark||'';\n    });\n  }\n  applyChecklist(data.panel,'f_pnl');\n  applyChecklist(data.door,'f_door');\n  applyChecklist(data.emergency,'f_emg');\n  applyChecklist(data.lightCurtain,'f_lc');\n  if(data.wire && data.wire.length){\n    data.wire.forEach(function(rowData,idx){\n      var sel=document.getElementById('f_wirerow'+idx+'_colour'); if(sel && rowData.selected) sel.value=rowData.selected;\n    });\n  }\n  (data.wireRemarks||[]).forEach(function(r,gi){ var e=document.getElementById('f_wire'+gi+'_remark'); if(e) e.value=r||''; });\n  (data.safety||[]).forEach(function(row){\n    var p='f_saf'+row.n;\n    var ma=document.getElementById(p+'_mainair'); if(ma && row.mainAir) ma.value=row.mainAir;\n    var el=document.getElementById(p+'_elec'); if(el && row.elec) el.value=row.elec;\n    if(row.ctrl){ var ctrlRadio=document.querySelector('input[name=\"'+p+'_ctrl\"][value=\"'+row.ctrl+'\"]'); if(ctrlRadio) ctrlRadio.checked=true; }\n    var ind=document.getElementById(p+'_indicator'); if(ind && row.indicator) ind.value=row.indicator;\n    if(row.status){ var radio=document.querySelector('input[name=\"'+p+'_status\"][value=\"'+row.status+'\"]'); if(radio) radio.checked=true; }\n    var r=document.getElementById(p+'_remark'); if(r) r.value=row.remark||'';\n  });\n  (data.tower||[]).forEach(function(row){\n    var p='f_twr'+row.n;\n    var st=document.getElementById(p+'_state'); if(st && row.colour) st.value=row.colour;\n    if(row.status){ var radio=document.querySelector('input[name=\"'+p+'_status\"][value=\"'+row.status+'\"]'); if(radio) radio.checked=true; }\n    var r=document.getElementById(p+'_remark'); if(r) r.value=row.remark||'';\n  });\n  if(data.doorLock){\n    if(data.doorLock.type){ var lockRadio=document.querySelector('input[name=\"f_doorlock_type\"][value=\"'+data.doorLock.type+'\"]'); if(lockRadio) lockRadio.checked=true; }\n    var dr=document.getElementById('f_doorlock_remark'); if(dr) dr.value=data.doorLock.remark||'';\n  }\n  if(data.signoff) Object.keys(data.signoff).forEach(function(k){ var e=document.getElementById('f_signoff_'+k); if(e) e.value=data.signoff[k]||''; });\n}\nfunction statusMsg(msg,ok){\n  var el=document.getElementById('pbFormStatusMsg');\n  el.style.color = ok===false ? '#b91c1c' : '#16a34a';\n  el.textContent = msg;\n  setTimeout(function(){ el.textContent=''; }, 5000);\n}\n\n// ---------- SUMMARY COMPUTATION ----------\nfunction computeSummary(data){\n  function qtyOf(name){\n    var d = data.devices.find(function(x){ return x.device === name; });\n    return d ? (parseInt(d.qty,10) || 0) : 0;\n  }\n  var s = {};\n  s.eStopCount = qtyOf('Emergency Stop');\n  s.pushButtonCount = PUSH_BUTTON_DEVICE_NAMES.reduce(function(sum,name){ return sum + qtyOf(name); }, 0);\n  s.selectorSwitchCount = qtyOf('Auto / Manual Selector Switch');\n  s.towerLampCount = qtyOf('Tower Lamp (3-tier R/Y/G)');\n  s.buzzerCount = qtyOf('Buzzer / Audible Alarm');\n\n  s.indicatorLampsByColour = {};\n  INDICATOR_LAMP_DEVICE_NAMES.forEach(function(name){\n    var d = data.devices.find(function(x){ return x.device === name; });\n    if(d){\n      var col = d.colour || 'Unspecified';\n      var qty = parseInt(d.qty,10) || 0;\n      s.indicatorLampsByColour[col] = (s.indicatorLampsByColour[col]||0) + qty;\n    }\n  });\n  s.indicatorLampTotal = Object.keys(s.indicatorLampsByColour).reduce(function(sum,k){ return sum + s.indicatorLampsByColour[k]; }, 0);\n\n  s.powerCableColours = {};\n  s.signalCableColours = {};\n  data.wire.forEach(function(r){\n    var col = r.selected || r.standard || 'Unspecified';\n    if(r.category === 'signal'){ s.signalCableColours[col] = (s.signalCableColours[col]||0) + 1; }\n    else { s.powerCableColours[col] = (s.powerCableColours[col]||0) + 1; }\n  });\n  return s;\n}\nfunction fmtColourMap(map){\n  var keys = Object.keys(map);\n  if(keys.length===0) return 'None specified';\n  return keys.map(function(k){ return k+': '+map[k]; }).join(', ');\n}\nfunction renderSummaryPanel(summary, data){\n  var html = '<div class=\"summary-box\"><h3>\ud83d\udccb Submission Summary</h3>';\n  html += '<div class=\"summary-grid\">';\n  html += '<div class=\"summary-card\"><div class=\"num\">'+summary.eStopCount+'</div><div class=\"lbl\">Emergency Stops</div></div>';\n  html += '<div class=\"summary-card\"><div class=\"num\">'+summary.pushButtonCount+'</div><div class=\"lbl\">Push Buttons (Start/Stop/Reset/Two-Hand)</div></div>';\n  html += '<div class=\"summary-card\"><div class=\"num\">'+summary.selectorSwitchCount+'</div><div class=\"lbl\">Selector Switches</div></div>';\n  html += '<div class=\"summary-card\"><div class=\"num\">'+summary.indicatorLampTotal+'</div><div class=\"lbl\">Indicator Lamps</div></div>';\n  html += '<div class=\"summary-card\"><div class=\"num\">'+summary.towerLampCount+'</div><div class=\"lbl\">Tower Lamps</div></div>';\n  html += '<div class=\"summary-card\"><div class=\"num\">'+summary.buzzerCount+'</div><div class=\"lbl\">Buzzers</div></div>';\n  html += '</div>';\n\n  html += '<table class=\"req-table\" style=\"margin-top:14px;background:#fff;\">';\n  html += '<tr><th>Category</th><th>Breakdown</th></tr>';\n  html += '<tr><td>Indicator Lamps by Colour</td><td>'+fmtColourMap(summary.indicatorLampsByColour)+'</td></tr>';\n  html += '<tr><td>Power Supply Cable Colours Used</td><td>'+fmtColourMap(summary.powerCableColours)+'</td></tr>';\n  html += '<tr><td>Signal Cable (PLC I/O) Colours Used</td><td>'+fmtColourMap(summary.signalCableColours)+'</td></tr>';\n  html += '<tr><td>Door Lock / Handle Type Selected</td><td>'+doorLockLabel(data.doorLock.type)+'</td></tr>';\n  html += '</table>';\n  html += '<p style=\"font-size:12.5px;color:#166534;\">Project: <b>'+(data.project.name||'\u2014')+'</b> | Code: <b>'+(data.project.code||'\u2014')+'</b> | Customer: <b>'+(data.project.customer||'\u2014')+'</b></p>';\n  html += '</div>';\n  document.getElementById('summaryPanel').innerHTML = html;\n  document.getElementById('summaryPanel').scrollIntoView({behavior:'smooth', block:'start'});\n}\n\n// ---------- DRAFT (localStorage) ----------\nvar DRAFT_PREFIX = 'pbSafetyForm_draft_';\nwindow.pbForm_saveDraft = function(){\n  var code = v('f_proj_code') || v('f_proj_name');\n  if(!code){ statusMsg('Enter a Project Number or Name before saving a draft.', false); return; }\n  var key = DRAFT_PREFIX + code.trim().toLowerCase();\n  localStorage.setItem(key, JSON.stringify(collectFormData()));\n  statusMsg('Draft saved on this device for \"'+code+'\".');\n};\nwindow.pbForm_loadDraftPrompt = function(){\n  var keys = Object.keys(localStorage).filter(function(k){ return k.indexOf(DRAFT_PREFIX)===0; });\n  if(keys.length===0){ statusMsg('No saved drafts found on this device.', false); return; }\n  var labels = keys.map(function(k){ return k.replace(DRAFT_PREFIX,''); });\n  var pick = prompt('Saved drafts:\\n' + labels.map(function(l,i){return (i+1)+'. '+l;}).join('\\n') + '\\n\\nType the number to load:');\n  if(!pick) return;\n  var idx = parseInt(pick,10) - 1;\n  if(isNaN(idx) || idx<0 || idx>=keys.length){ statusMsg('Invalid selection.', false); return; }\n  try{\n    var data = JSON.parse(localStorage.getItem(keys[idx]));\n    applyFormData(data);\n    statusMsg('Draft \"'+labels[idx]+'\" loaded.');\n  }catch(e){ statusMsg('Could not load that draft.', false); }\n};\n\n// ---------- EXCEL EXPORT ----------\nfunction loadScriptOnce(src, globalCheck, cb){\n  if(globalCheck()){ cb(); return; }\n  var s = document.createElement('script');\n  s.src = src;\n  s.onload = cb;\n  s.onerror = function(){ statusMsg('Could not load export library. Check your internet connection.', false); };\n  document.body.appendChild(s);\n}\nfunction buildWorkbook(data, summary){\n  var wb = XLSX.utils.book_new();\n  function addSheet(name, rows){ var ws = XLSX.utils.aoa_to_sheet(rows); XLSX.utils.book_append_sheet(wb, ws, name.substring(0,31)); }\n\n  var summaryRows = [['Metric','Value']];\n  summaryRows.push(['Emergency Stops', summary.eStopCount]);\n  summaryRows.push(['Push Buttons (Start/Stop/Reset/Two-Hand)', summary.pushButtonCount]);\n  summaryRows.push(['Selector Switches', summary.selectorSwitchCount]);\n  summaryRows.push(['Indicator Lamps - Total', summary.indicatorLampTotal]);\n  summaryRows.push(['Tower Lamps', summary.towerLampCount]);\n  summaryRows.push(['Buzzers', summary.buzzerCount]);\n  summaryRows.push(['', '']);\n  summaryRows.push(['Indicator Lamps by Colour','']);\n  Object.keys(summary.indicatorLampsByColour).forEach(function(k){ summaryRows.push([k, summary.indicatorLampsByColour[k]]); });\n  summaryRows.push(['', '']);\n  summaryRows.push(['Power Supply Cable Colours Used','']);\n  Object.keys(summary.powerCableColours).forEach(function(k){ summaryRows.push([k, summary.powerCableColours[k]]); });\n  summaryRows.push(['', '']);\n  summaryRows.push(['Signal Cable (PLC I/O) Colours Used','']);\n  Object.keys(summary.signalCableColours).forEach(function(k){ summaryRows.push([k, summary.signalCableColours[k]]); });\n  addSheet('Summary', summaryRows);\n\n  addSheet('Project Info', [['Field','Value']].concat(Object.keys(data.project).map(function(k){return [k, data.project[k]];})));\n  addSheet('PB-Indicators', [['#','Device','Type','Colour','Background Colour','Qty','Remark']]\n    .concat(data.devices.map(function(d,i){return [i+1,d.device,d.type,d.colour,d.background,d.qty,d.remark];})));\n  addSheet('Panel Requirements', [['Sr','Point','Compliance','Remark']].concat(data.panel.map(function(r){return [r.sr,r.point,r.status,r.remark];})));\n  addSheet('Door Lock Selection', [['Field','Value'],['Selected Lock Type', doorLockLabel(data.doorLock.type)],['Remark', data.doorLock.remark || '']]);\n  addSheet('Wire Colour Coding', [['Supply','Item','Category','Standard Colour','Selected Colour','Remark']]\n    .concat(data.wire.map(function(r){return [r.supply,r.item,r.category,r.standard,r.selected,r.remark];})));\n  addSheet('Safety Light Logic', [['#','Condition','Mode','Main Air','Elec Movement','Safety Ctrl','Indicator','Description','Compliance','Remark']]\n    .concat(data.safety.map(function(r){return [r.n,r.condition,r.mode,r.mainAir,r.elec,r.ctrl,r.indicator,r.desc,r.status,r.remark];})));\n  addSheet('Tower Lamp Logic', [['#','State','Meaning','Compliance','Remark']].concat(data.tower.map(function(r){return [r.n,r.colour,r.meaning,r.status,r.remark];})));\n  addSheet('Door Safety Logic', [['Sr','Point','Compliance','Remark']].concat(data.door.map(function(r){return [r.sr,r.point,r.status,r.remark];})));\n  addSheet('Emergency Logic', [['Sr','Point','Compliance','Remark']].concat(data.emergency.map(function(r){return [r.sr,r.point,r.status,r.remark];})));\n  addSheet('Light Curtain Logic', [['Sr','Point','Compliance','Remark']].concat(data.lightCurtain.map(function(r){return [r.sr,r.point,r.status,r.remark];})));\n  addSheet('Sign-off', [['Field','Value']].concat(Object.keys(data.signoff).map(function(k){return [k, data.signoff[k]];})));\n  return wb;\n}\nwindow.pbForm_downloadExcel = function(){\n  loadScriptOnce('https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js', function(){ return !!window.XLSX; }, function(){\n    var data = collectFormData();\n    var summary = computeSummary(data);\n    var wb = buildWorkbook(data, summary);\n    var filename = 'PB_Indicator_Safety_Form_' + (data.project.code || data.project.name || 'draft') + '.xlsx';\n    XLSX.writeFile(wb, filename.replace(/[^a-z0-9_\\-\\.]/gi,'_'));\n    statusMsg('Excel file downloaded.');\n  });\n};\n\n// ---------- PDF EXPORT ----------\nfunction buildPrintHTML(data, summary){\n  function checklistRows(arr){ return arr.map(function(r){ return '<tr><td>'+r.sr+'</td><td>'+r.point+'</td><td>'+(r.status||'')+'</td><td>'+(r.remark||'')+'</td></tr>'; }).join(''); }\n  var h = '<div style=\"font-family:Arial;padding:10px;\">';\n  h += '<h1 style=\"color:#2563eb;\">Push Buttons, Indicators, Panel Wiring &amp; Safety Logic \u2014 Requirement Form</h1>';\n\n  if(summary){\n    h += '<h3>Submission Summary</h3><table><tr><th>Metric</th><th>Value</th></tr>'+\n      '<tr><td>Emergency Stops</td><td>'+summary.eStopCount+'</td></tr>'+\n      '<tr><td>Push Buttons</td><td>'+summary.pushButtonCount+'</td></tr>'+\n      '<tr><td>Selector Switches</td><td>'+summary.selectorSwitchCount+'</td></tr>'+\n      '<tr><td>Indicator Lamps (Total)</td><td>'+summary.indicatorLampTotal+' \u2014 '+fmtColourMap(summary.indicatorLampsByColour)+'</td></tr>'+\n      '<tr><td>Tower Lamps</td><td>'+summary.towerLampCount+'</td></tr>'+\n      '<tr><td>Buzzers</td><td>'+summary.buzzerCount+'</td></tr>'+\n      '<tr><td>Power Supply Cable Colours</td><td>'+fmtColourMap(summary.powerCableColours)+'</td></tr>'+\n      '<tr><td>Signal Cable Colours</td><td>'+fmtColourMap(summary.signalCableColours)+'</td></tr>'+\n      '</table>';\n  }\n\n  h += '<h3>Project Information</h3><table><tr><th>Field</th><th>Value</th></tr>' +\n    Object.keys(data.project).map(function(k){return '<tr><td>'+k+'</td><td>'+data.project[k]+'</td></tr>';}).join('') + '</table>';\n\n  h += '<h3>PB / Indicator / Tower Lamp Devices</h3><table><tr><th>#</th><th>Device</th><th>Type</th><th>Colour</th><th>Background Colour</th><th>Qty</th><th>Remark</th></tr>' +\n    data.devices.map(function(d,i){return '<tr><td>'+(i+1)+'</td><td>'+d.device+'</td><td>'+d.type+'</td><td>'+d.colour+'</td><td>'+d.background+'</td><td>'+d.qty+'</td><td>'+d.remark+'</td></tr>';}).join('') + '</table>';\n\n  h += '<h3>Electrical Panel Requirements</h3><table><tr><th>Sr</th><th>Point</th><th>Compliance</th><th>Remark</th></tr>' + checklistRows(data.panel) + '</table>';\n\n  var selectedLockOpt = DOOR_LOCK_OPTIONS.find(function(o){ return o.id === data.doorLock.type; });\n  h += '<h3>Door Lock / Handle Type Selected</h3><table><tr><th>Field</th><th>Value</th></tr>'+\n    '<tr><td>Selected Lock Type</td><td>'+(selectedLockOpt?selectedLockOpt.label:'Not selected')+'</td></tr>'+\n    '<tr><td>Remark</td><td>'+(data.doorLock.remark||'')+'</td></tr></table>';\n  if(selectedLockOpt){ h += '<img src=\"'+selectedLockOpt.img+'\" style=\"width:140px;height:140px;object-fit:contain;border:1px solid #94a3b8;margin:4px 0 10px;\">'; }\n\n  h += '<h3>Wire Colour Coding</h3><table><tr><th>Supply</th><th>Item</th><th>Category</th><th>Standard Colour</th><th>Selected Colour</th><th>Remark</th></tr>' +\n    data.wire.map(function(r){return '<tr><td>'+r.supply+'</td><td>'+r.item+'</td><td>'+r.category+'</td><td>'+r.standard+'</td><td>'+r.selected+'</td><td>'+r.remark+'</td></tr>';}).join('') + '</table>';\n\n  h += '<h3>Safety Indicator Light Logic</h3><table><tr><th>#</th><th>Condition</th><th>Mode</th><th>Main Air</th><th>Elec Mvt</th><th>Safety Ctrl</th><th>Indicator</th><th>Description</th><th>Compliance</th><th>Remark</th></tr>' +\n    data.safety.map(function(r){return '<tr><td>'+r.n+'</td><td>'+r.condition+'</td><td>'+r.mode+'</td><td>'+r.mainAir+'</td><td>'+r.elec+'</td><td>'+r.ctrl+'</td><td>'+r.indicator+'</td><td>'+r.desc+'</td><td>'+r.status+'</td><td>'+r.remark+'</td></tr>';}).join('') + '</table>';\n\n  h += '<h3>Tower Lamp Logic</h3><table><tr><th>#</th><th>State</th><th>Meaning</th><th>Compliance</th><th>Remark</th></tr>' +\n    data.tower.map(function(r){return '<tr><td>'+r.n+'</td><td>'+r.colour+'</td><td>'+r.meaning+'</td><td>'+r.status+'</td><td>'+r.remark+'</td></tr>';}).join('') + '</table>';\n\n  h += '<h3>Door Safety &amp; Reset Logic</h3><table><tr><th>Sr</th><th>Point</th><th>Compliance</th><th>Remark</th></tr>' + checklistRows(data.door) + '</table>';\n  h += '<h3>Emergency Stop &amp; Reset Logic</h3><table><tr><th>Sr</th><th>Point</th><th>Compliance</th><th>Remark</th></tr>' + checklistRows(data.emergency) + '</table>';\n  h += '<h3>Light Curtain Logic</h3><table><tr><th>Sr</th><th>Point</th><th>Compliance</th><th>Remark</th></tr>' + checklistRows(data.lightCurtain) + '</table>';\n\n  h += '<h3>Sign-off</h3><table><tr><th>Field</th><th>Value</th></tr>' +\n    Object.keys(data.signoff).map(function(k){return '<tr><td>'+k+'</td><td>'+data.signoff[k]+'</td></tr>';}).join('') + '</table>';\n  h += '</div>';\n  return h;\n}\nwindow.pbForm_downloadPDF = function(){\n  loadScriptOnce('https://cdnjs.cloudflare.com/ajax/libs/html2pdf.js/0.10.1/html2pdf.bundle.min.js', function(){ return !!window.html2pdf; }, function(){\n    var data = collectFormData();\n    var summary = computeSummary(data);\n    var printRoot = document.createElement('div');\n    printRoot.id = 'pdfPrintOverlayRoot';\n    printRoot.style.background = '#fff';\n    printRoot.style.width = '1400px';\n    printRoot.innerHTML = buildPrintHTML(data, summary);\n\n    var overlay = document.createElement('div');\n    overlay.id = 'pdfPrintOverlay';\n    overlay.style.position = 'fixed';\n    overlay.style.inset = '0';\n    overlay.style.zIndex = '99999';\n    overlay.style.background = '#fff';\n    overlay.style.overflow = 'auto';\n    overlay.appendChild(printRoot);\n    document.body.appendChild(overlay);\n\n    var opt = {\n      margin: 8,\n      filename: 'PB_Indicator_Safety_Form_' + (data.project.code || data.project.name || 'draft').replace(/[^a-z0-9_\\-\\.]/gi,'_') + '.pdf',\n      image: { type: 'jpeg', quality: 0.98 },\n      html2canvas: { scale: 2, useCORS: true },\n      jsPDF: { unit: 'mm', format: 'a4', orientation: 'landscape' }\n    };\n\n    setTimeout(function(){\n      html2pdf().set(opt).from(printRoot).save().then(function(){\n        document.body.removeChild(overlay);\n        statusMsg('PDF downloaded.');\n      }).catch(function(){\n        document.body.removeChild(overlay);\n        statusMsg('PDF generation failed.', false);\n      });\n    }, 150);\n  });\n};\n\n// ---------- SUBMIT (summary + downloads + mailto) ----------\nfunction buildEmailBody(data, summary){\n  var lines = [];\n  lines.push('DRB TechVerse \u2014 PB, Indicator & Panel Safety Requirement Form \u2014 Completed Submission');\n  lines.push('');\n  lines.push('Project Name: ' + (data.project.name||'-'));\n  lines.push('Project Code: ' + (data.project.code||'-'));\n  lines.push('Customer: ' + (data.project.customer||'-'));\n  lines.push('Machine/Module: ' + (data.project.machine||'-'));\n  lines.push('Site: ' + (data.project.site||'-'));\n  lines.push('Date: ' + (data.project.date||'-'));\n  lines.push('');\n  lines.push('--- SUMMARY ---');\n  lines.push('Emergency Stops: ' + summary.eStopCount);\n  lines.push('Push Buttons (Start/Stop/Reset/Two-Hand): ' + summary.pushButtonCount);\n  lines.push('Selector Switches: ' + summary.selectorSwitchCount);\n  lines.push('Indicator Lamps (Total): ' + summary.indicatorLampTotal + ' [' + fmtColourMap(summary.indicatorLampsByColour) + ']');\n  lines.push('Tower Lamps: ' + summary.towerLampCount);\n  lines.push('Buzzers: ' + summary.buzzerCount);\n  lines.push('Power Supply Cable Colours Used: ' + fmtColourMap(summary.powerCableColours));\n  lines.push('Signal Cable (PLC I/O) Colours Used: ' + fmtColourMap(summary.signalCableColours));\n  lines.push('Door Lock / Handle Type Selected: ' + doorLockLabel(data.doorLock.type));\n  lines.push('');\n  lines.push('The fully completed Excel and PDF files were downloaded to this device just before this email opened.');\n  lines.push('Please ATTACH both downloaded files (\"PB_Indicator_Safety_Form_...xlsx\" and \"...pdf\") to this email before sending.');\n  lines.push('');\n  lines.push('Sent from the DRB TechVerse Customer Requirement Form.');\n  return lines.join('\\n');\n}\nwindow.pbForm_submit = function(){\n  var data = collectFormData();\n  if(!data.project.name && !data.project.code){\n    statusMsg('Please fill in the Project Name or Project Code before submitting.', false);\n    document.getElementById('f_proj_name').focus();\n    return;\n  }\n  if(!data.project.customer){\n    statusMsg('Please fill in the Customer Name before submitting.', false);\n    document.getElementById('f_proj_customer').focus();\n    return;\n  }\n  var summary = computeSummary(data);\n  renderSummaryPanel(summary, data);\n  statusMsg('Summary generated. Downloading Excel and PDF, then opening your email app\u2026');\n\n  pbForm_downloadExcel();\n  setTimeout(function(){ pbForm_downloadPDF(); }, 900);\n  setTimeout(function(){\n    var subject = 'PB, Indicator & Panel Safety Form Submission - ' + (data.project.name || data.project.code || 'Unnamed Project');\n    var body = buildEmailBody(data, summary);\n    var mailto = 'mailto:' + encodeURIComponent(ADMIN_EMAIL) + '?subject=' + encodeURIComponent(subject) + '&body=' + encodeURIComponent(body);\n    window.location.href = mailto;\n    statusMsg('Email draft opened \u2014 please attach the downloaded Excel & PDF, then click Send.');\n  }, 2200);\n};\n\n})();\n";

export default function CustomerPbIndicatorFormPage() {
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    container.innerHTML = FORM_HTML;

    const script = document.createElement("script");
    script.textContent = FORM_JS;
    document.body.appendChild(script);

    return () => {
      document.body.removeChild(script);
      if (container) container.innerHTML = "";
      // Clean up the global handlers the injected script attaches to window
      // so a stale copy can't be called after this page unmounts.
      delete (window as any).pbForm_saveDraft;
      delete (window as any).pbForm_loadDraftPrompt;
      delete (window as any).pbForm_downloadExcel;
      delete (window as any).pbForm_downloadPDF;
      delete (window as any).pbForm_submit;
    };
  }, []);

  return (
    <div style={{ padding: "24px 16px 60px" }}>
      <div style={{ maxWidth: 1150, margin: "0 auto 16px" }}>
        <Link
          href="/"
          style={{
            display: "inline-flex",
            alignItems: "center",
            gap: 6,
            fontSize: 14,
            fontWeight: 500,
            color: "#2563eb",
            textDecoration: "none",
          }}
        >
          <ArrowLeft size={16} />
          Back to Dashboard
        </Link>
      </div>
      <div ref={containerRef} />
    </div>
  );
}
